  justify-content: space-between;
  align-items: center;
  gap: var(--space-s);
  padding: var(--space-s) var(--space-m);
  font-weight: 600;
  cursor: pointer;
  list-style: none;

  &::-webkit-details-marker {
    display: none;
  }

  &::after {
    content: "+";
    display: grid;
    flex: none;
    place-items: center;
    inline-size: to-rem(32px);
    block-size: to-rem(32px);
    border-radius: 50%;
    background-color: var(--main-line-on-primary);
    font-size: var(--text-l);
    line-height: 1;
    transition: background-color 0.2s ease;
  }

  @media (width <= 768px) {
    padding-inline: var(--space-s);
  }

mn-faq-answer.css:
padding: var(--space-s) var(--space-m);
  background-color: var(--main-light);
  color: var(--main-text);

  @media (width <= 768px) {
    padding-inline: var(--space-s);
  }

